<script setup lang="ts">
import {ref,onMounted} from 'vue';
import type {World,Point} from '../../../packages/shared/src/types';
const props=defineProps<{world:World;tab:string;tile?:Point}>(),emit=defineEmits(['updated','switch']);
const error=ref(''),residentId=ref('resident-009'),name=ref('新来的拓荒者'),type=ref('FOOD_STALL'),building=ref(''),text=ref('我们会认真考虑居民的困难。'),minutes=ref(60),worlds=ref<any[]>([]),scenarioId=ref('starter'),events=ref<any[]>([]),experiment=ref<any>(),providerId=ref(''),llmProviderId=ref(''),providers=ref<any[]>([]),metrics=ref<any>();
async function api(path:string,b?:any){const r=await fetch(path,{method:b?'POST':'GET',headers:{'content-type':'application/json'},body:b?JSON.stringify(b):undefined});const v=await r.json();if(!r.ok)throw new Error(v.message);return v;}
async function command(action:string,extra:any={}){try{emit('updated',await api(`/api/worlds/${props.world.id}/frontier`,{action,...extra,key:crypto.randomUUID(),expectedVersion:props.world.version}));error.value='';}catch(e:any){error.value=e.message;}}
async function settings(){try{emit('updated',await api(`/api/worlds/${props.world.id}/settings`,{aiEnabled:!props.world.settings.aiEnabled,key:crypto.randomUUID(),expectedVersion:props.world.version}));}catch(e:any){error.value=e.message;}}
async function create(){try{const w=await api('/api/worlds',{scenarioId});worlds.value=await api('/api/worlds');emit('switch',w.id);}catch(e:any){error.value=e.message;}}
async function exportSave(){try{const data=await api(`/api/worlds/${props.world.id}/export`,{}),url=URL.createObjectURL(new Blob([JSON.stringify(data)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`frontier-${props.world.id}.json`;a.click();URL.revokeObjectURL(url);}catch(e:any){error.value=e.message;}}
async function restore(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;try{const w=await api('/api/worlds/restore',JSON.parse(await file.text()));emit('switch',w.id);}catch(e:any){error.value=e.message;}}
async function compare(){try{experiment.value=await api(`/api/worlds/${props.world.id}/decision-experiment`,{residentId:residentId.value,providerId:providerId.value||undefined,llmProviderId:llmProviderId.value||undefined});}catch(e:any){error.value=e.message;}}
onMounted(async()=>{try{worlds.value=await api('/api/worlds');events.value=await api(`/api/worlds/${props.world.id}/events`);metrics.value=await api(`/api/worlds/${props.world.id}/metrics`);providers.value=await api('/api/model-providers');}catch(e:any){error.value=e.message;}});
</script>
<template><div v-if="tab==='settings'"><h2>世界设置与存档</h2><button @click="settings">{{world.settings.aiEnabled?'暂停AI（基本模拟继续）':'启用AI'}}</button><button @click="command('fastForward',{minutes})">暂停后快进</button><label>游戏分钟<input type="number" v-model.number="minutes" min="1" max="180"></label><button @click="exportSave">导出存档（不含模型密钥）</button><label>恢复至新世界<input type="file" accept="application/json" @change="restore"></label><h3>独立世界</h3><button v-for="w in worlds" @click="emit('switch',w.id)">{{w.name}} · {{w.id.slice(0,8)}}</button><select v-model="scenarioId"><option value="starter">晨沙镇·标准开拓</option><option value="scarcity">暮风营地·资源压力</option></select><button @click="create">创建独立世界</button></div>
<div v-else-if="tab==='events'"><h2>公告与故事回放</h2><p>天气 {{world.weather?.type??'晴朗'}} · {{world.weather?.warning}}</p><div v-for="r in (world.reports??[]).slice(-5).reverse()" class="notice"><strong>第{{r.day}}天 · {{r.headline}}</strong><p v-for="s in r.summary">{{s}}</p></div><details><summary>运行指标</summary><p v-if="metrics">Tick 样本 {{metrics.tick.recentSamples}} · 近期均进度 {{metrics.tick.meanGameMinutesPerTick?.toFixed(1)??'暂无'}} 游戏分钟/Tick</p><p v-if="metrics">AI 队列 {{metrics.ai.pending}} 待处理 · {{metrics.ai.circuitsOpen}} 熔断中 · {{metrics.ai.usageSamples}} 次调用记录</p><p v-if="metrics">账本 {{metrics.ledger.balanced?'平衡':'需核查'}} · WebSocket {{metrics.websocketConnections}} 个连接</p><p v-if="error" class="error">{{error}}</p></details><details><summary>完整公开事件历史</summary><p v-for="e in events.slice(-100).reverse()">#{{e.event_seq}} {{e.type}} · 游戏时间{{e.game_time.toFixed(0)}} · {{e.payload}}</p></details><h3>社群与技术</h3><p>{{world.civilization?.technologies?.join('、')||'尚未解锁技术'}}</p><p v-for="c in world.civilization?.communities">{{c.name}} · {{c.members.length}}人</p><h3>公共委员会</h3><p>财政、水务、医疗与工头的意见保存在每项提案的公议记录中；正式选举随玩法成熟度另行确认。</p></div>
<div v-else-if="tab==='experiments'"><h2>决策实验</h2><select v-model="residentId"><option v-for="r in world.residents" :value="r.id">{{r.name}}</option></select><label>LLM 供应商<select v-model="llmProviderId"><option value="">不调用 LLM</option><option v-for="p in providers.filter(x=>x.protocol==='OPENAI'&&x.enabled)" :value="p.id">{{p.name}} · {{p.model}}</option></select></label><label>Jev供应商标识<input v-model="providerId" placeholder="留空跳过 Jev 请求"></label><button @click="compare">运行对比（LLM/Jev 各最多3次调用）</button><template v-if="experiment"><h3>规则基线</h3><p>{{experiment.rules.metrics.samples}} 次 · 均延迟 {{experiment.rules.metrics.meanLatencyMs}} ms · 回退 {{experiment.rules.metrics.fallbacks}} · 态度一致 {{experiment.rules.metrics.attitudeStability===null?'样本不足':Math.round(experiment.rules.metrics.attitudeStability*100)+'%'}}</p><h3>LLM 本次样本</h3><p>{{experiment.llm.samples}} 次 · 均延迟 {{experiment.llm.meanLatencyMs??'暂无'}} ms · 均费用 {{experiment.llm.meanCost??'暂无'}} · 角色立场一致 {{experiment.llm.characterConsistency===null?'无可比样本':Math.round(experiment.llm.characterConsistency*100)+'%'}}</p><h3>Jev 当前样本</h3><p>{{experiment.selected?`${experiment.selected.metrics.samples} 次 · 均延迟 ${experiment.selected.metrics.meanLatencyMs} ms · 均费用 ${experiment.selected.metrics.meanCost??'未知'} · 回退 ${experiment.selected.metrics.fallbacks} · 态度稳定 ${experiment.selected.metrics.attitudeStability===null?'样本不足':Math.round(experiment.selected.metrics.attitudeStability*100)+'%'} · 角色立场一致 ${experiment.selected.metrics.characterConsistency===null?'无样本':Math.round(experiment.selected.metrics.characterConsistency*100)+'%'}`:'未选择有效 Jev 供应商'}}</p><h3>公共委员会意见</h3><p v-for="r in experiment.committee.records">{{r.role}}：{{r.view}} · {{r.reason}}</p><p>{{experiment.limitation}}</p><details><summary>原始决策信号</summary><pre>{{JSON.stringify({rules:experiment.rules.answers,llm:experiment.llm,jev:experiment.selected?.answers},null,2)}}</pre></details></template></div>
<div v-else><h2>沙海探索与居民生活</h2><p>当前地图 {{world.map.width}}×{{world.map.height}} · 选中 {{tile?.x??'—'}}, {{tile?.y??'—'}}</p><select v-model="residentId"><option v-for="r in world.residents" :value="r.id">{{r.name}}</option></select><button :disabled="!tile" @click="command('explore',{site:tile,team:[residentId]})">邀请探索（需补给与空闲）</button><button @click="command('expand')">勘察后并入新区块</button><h3>新移民</h3><input v-model="name" aria-label="新移民名称"><button @click="command('migrate',{name})">审核并安置（需住房/粮水）</button><h3>创业与搬迁</h3><select v-model="type"><option v-for="t in ['WORKSHOP','FOOD_STALL','WATER_REPAIR']">{{t}}</option></select><button @click="command('business',{residentId,type})">居民创业（私人资金）</button><select v-model="building"><option v-for="b in world.map.structures.filter(b=>['TENT','HOUSING'].includes(b.type))" :value="b.id">{{b.name}}</option></select><button @click="command('move',{residentId,buildingId:building})">申请搬迁</button><h3>访客拜访</h3><textarea v-model="text"></textarea><button @click="command('visit',{residentId,text})">走进小镇与居民交谈</button><h3>邻近聚落</h3><div v-for="s in world.civilization?.diplomacy"><p>{{s.name}} · 信任{{s.trust}}</p><button @click="command('diplomacy',{settlementId:s.id,type:'NEGOTIATE'})">协商</button><button @click="command('diplomacy',{settlementId:s.id,type:'TRADE'})">贸易运送10份粮（30金币）</button></div></div><p class="error">{{error}}</p></template>
